CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE (display_name) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY "Update own profile" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE FUNCTION public.create_earnright_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (new.id, coalesce(new.raw_user_meta_data->>'display_name', 'Member')); RETURN new; END; $$;
CREATE TRIGGER earnright_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_earnright_profile();
CREATE TABLE public.demo_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, activity_key text NOT NULL, title text NOT NULL, credits integer NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, activity_key));
GRANT SELECT ON public.demo_activity TO authenticated;
GRANT ALL ON public.demo_activity TO service_role;
ALTER TABLE public.demo_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own demo activity" ON public.demo_activity FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE TABLE public.demo_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, activity_key text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, activity_key));
GRANT SELECT ON public.demo_sessions TO authenticated;
GRANT ALL ON public.demo_sessions TO service_role;
ALTER TABLE public.demo_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own demo sessions" ON public.demo_sessions FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE FUNCTION public.start_demo_activity(activity text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF activity NOT IN ('game','video','task') THEN RAISE EXCEPTION 'Unknown activity'; END IF; INSERT INTO public.demo_sessions(user_id, activity_key) VALUES (auth.uid(), activity) ON CONFLICT (user_id, activity_key) DO UPDATE SET started_at = now(); END; $$;
REVOKE ALL ON FUNCTION public.start_demo_activity(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.start_demo_activity(text) TO authenticated;
CREATE FUNCTION public.complete_demo_activity(activity text, answer text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE started timestamptz; reward integer; label text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT started_at INTO started FROM public.demo_sessions WHERE user_id = auth.uid() AND activity_key = activity FOR UPDATE; IF started IS NULL THEN RAISE EXCEPTION 'Start the activity first'; END IF; IF activity = 'task' THEN IF answer <> '4' THEN RAISE EXCEPTION 'That answer is not correct. Try again.'; END IF; reward := 30; label := 'Quick knowledge check'; ELSIF activity = 'game' THEN IF now() - started < interval '15 seconds' THEN RAISE EXCEPTION 'Finish the round first'; END IF; reward := 50; label := 'Reaction round'; ELSIF activity = 'video' THEN IF now() - started < interval '20 seconds' THEN RAISE EXCEPTION 'Watch the full preview first'; END IF; reward := 20; label := 'EarnRight introduction'; ELSE RAISE EXCEPTION 'Unknown activity'; END IF; INSERT INTO public.demo_activity(user_id, activity_key, title, credits) VALUES (auth.uid(), activity, label, reward) ON CONFLICT (user_id, activity_key) DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.complete_demo_activity(text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_demo_activity(text,text) TO authenticated;